function getContext() {
    const { context } = api;

    return JSON.stringify(context);
}

function getConstant(msg) {
    let { distirbutorId } = JSON.parse(msg);
    const { code } = JSON.parse(msg);
    if (!distirbutorId) {
        distirbutorId = api.context.distirbutorId;
    }
    const res = api.constants.value(code, distirbutorId);
    api.log.info(`check constant res ${JSON.stringify(res)}`);

    return JSON.stringify(res);
}

