let bufferVar = '';
function updateBufferVar(msg) {
    bufferVar += msg;
}

function evalAndCallFunctionInBack(msg) {
    const msgParsed = JSON.parse(msg);
    const { useBufferVarForArgs } = msgParsed;
    const { functionCode, args = [] } = useBufferVarForArgs ? JSON.parse(bufferVar) : msgParsed;
    bufferVar = '';

    const strToEval = functionCode.startsWith('function') ? `const f = ${functionCode}; return f(...args);` : functionCode;
    const f = new Function('args', strToEval);
    const res = f(args);

    return JSON.stringify(res);
}

function callFnwithBufferVarArgs(msg) {
    const { functionName } = JSON.parse(msg);
    const argsStr = bufferVar;
    bufferVar = '';
    return global[functionName](argsStr);
}

