function callLibsFunction(msg) {
    const { functionName, args = [] } = JSON.parse(msg);
    const callRes = libsFunctions[functionName](...args);
    api.log.info('callLibsFunction callRes ', JSON.stringify(callRes));
    return JSON.stringify(callRes);
}

function callBackGlobalFunction(msg) {
    const { functionName, args = [] } = JSON.parse(msg);
    const strToEval = `const f = ${functionName}; return f(...args);`;
    const f = new Function('args', strToEval);
    const res = f(args);
    return JSON.stringify(res);
}

function isTableExists(msg) {
    const { tableName } = JSON.parse(msg);
    api.sql.exec(`PRAGMA table_info(${tableName})`);

    return JSON.stringify(Boolean(api.sql.rows().length));
}