class Cache {
    /**
     * Записывает в кэш знаение
     * @param {string} cacheName
     * @param {string} key
     * @param {any} value
     */
    static insert(cacheName, key, value) {
        api.cache.setCacheKey(cacheName);
        api.cache.insert(key, value);
    }

    /**
     * Получает значение из кэша по ключу
     * @param {string} cacheName
     * @param {string} key
     * @returns {string | null} значение по заданному ключу, null - значение отсутствует
     */
    static getValue(cacheName, key) {
        let result = null;

        api.cache.setCacheKey(cacheName);

        if (api.cache.contains(key)) {
            result = api.cache.value(key);
        } else {
            api.log.warn(`Ключ ${key} не найден в кэше ${cacheName}`);
        }

        return result;
    }

    /**
     * Удаляет из кэша ключ и его значение
     * @param {string} cacheName
     * @param {string} key
     */
    static remove(cacheName, key) {
        api.cache.setCacheKey(cacheName);
        api.cache.remove(key);
    }
}

module.exports = Cache;
