/**
 * Создаение пустого(незаполненного) документа ол
 * @param {object} options
 * @param {string} options.idTemplate - id шаблона ОЛ
 * @param {boolean} [options.checkHistory] - проверка историчности для ол
 * @return {OKR_CRUD_Questionnaire} объект
 */
function createQuestionnaireObject({ idTemplate, checkHistory = true }) {
    const questionsKeysWithHistory = {};

    const resp = [];

    const sqlQueryTemplate = `SELECT
      templ.id AS idTemplate, 
      templ.idFirstVersion AS idTemplateFV,
      templ.Name AS templateName,
      templ.Comment AS templateComment,
      templ.idViewMode AS idViewMode,
      qt.id AS idTopic,
      qt.Name AS topicName,
      qtr.id AS idTemplateRow,
      qtr.IsReadOnly AS IsReadOnly,
      qtr.IsRequired AS IsRequired,
      rg.id AS idQuestion,
      rg.FullName AS questionName,
      qtr.minVal AS minVal,
      qtr.maxVal AS maxVal,
      qtr.idLastAnswerKind AS idLastAnswerKind,
      eb.CodeKey AS questionType
      FROM refQstTemplates AS templ
      JOIN refQstTemplatesTopics AS qtt ON qtt.idTemplate = templ.id
      JOIN refQstTopics AS qt ON qt.id = qtt.idTopic
      JOIN refQstTemplatesRows AS qtr ON qtr.idTemplateTopic = qtt.id
      JOIN refGoods AS rg ON rg.id = qtr.idQuestion
      JOIN Enums AS eb ON eb.id = qtr.idAnswerType
      -- JOIN (
      --    SELECT idItem AS idItem, max(EventDate) AS EventDate FROM refPropertiesHistory AS ph 
      --    WHERE date(ph.EventDate) <= date('now', 'localtime')
      --    GROUP BY idItem
      -- ) AS phDate ON phDate.idItem = templ.id
      -- JOIN refPropertiesHistory AS ph ON ph.EventDate = phDate.EventDate AND ph.idItem = phDate.idItem
      -- WHERE templ.deleted = 0
      -- AND ph.idEvent = 133 AND ph.deleted = 0
      WHERE templ.id = ${idTemplate}
      ORDER BY qtt.Priority ASC, qtr.Priority ASC`;

    api.sql.exec(sqlQueryTemplate);
    const objQst = api.sql.rows();

    objQst.forEach((item) => {
        if (
            !resp.find((template) => item.idTemplate === template.idTemplate)
        ) {
            const template = {};

            template.docId = '0';
            template.idFirstVersion = '0';
            template.idPreviousVersion = '0';
            template.idStatus = '8';
            template.deleted = '0';
            template.idVisit = '0';
            template.idOutlet = '0';
            template.idPhysicalPerson = '0';
            template.idRoute = '0';
            template.idPosition = '0';
            template.docComment = '';
            template.idTemplate = item.idTemplate;
            template.idTemplateFV = item.idTemplateFV;
            template.templateComment = item.templateComment;
            template.idViewMode = item.idViewMode;
            template.templateName = item.templateName;
            template.topics = [];
            resp.push(template);
        }

        if (
            !resp
                .find((template) => item.idTemplate === template.idTemplate)
                .topics.some((topic) => item.idTopic === topic.idTopic)
        ) {
            const topic = {};

            topic.idTopic = item.idTopic;
            topic.topicName = item.topicName;
            topic.rows = [];
            resp
                .find((template) => item.idTemplate === template.idTemplate)
                .topics.push(topic);
        }

        if (
            !resp
                .find((template) => item.idTemplate === template.idTemplate)
                .topics.find((topic) => item.idTopic === topic.idTopic)
                .rows.some((templateRow) => item.idTemplateRow === templateRow.idTemplateRow)
        ) {
            const templateRow = {};

            if (item.idLastAnswerKind === '751') {
                questionsKeysWithHistory[item.idTopic + item.idQuestion] = 1;
            }

            templateRow.drSurveyId = '0';
            templateRow.idPacket = '0';
            templateRow.idTemplateRow = item.idTemplateRow;
            templateRow.idQuestion = item.idQuestion;
            templateRow.IsReadOnly = item.IsReadOnly;
            templateRow.IsRequired = item.IsRequired;
            templateRow.questionName = item.questionName;
            templateRow.questionType = item.questionType;
            templateRow.minVal = item.minVal;
            templateRow.maxVal = item.maxVal;
            templateRow.answers = [];
            templateRow.photos = [];
            templateRow.optionsList = [];
            templateRow.defValues = [];

            templateRow.answers.push(JSON.parse(JSON.stringify(emptyAnswer)));

            // Получаем Варианты ответов
            const sqlQueryAnswers = `SELECT
              qa.id AS QuestionAnswerId,
              qsa.id AS AnswerId,
              qsa.Value AS Name,
              qsa.GroupName AS GroupName
              FROM refQstTemplatesRows AS qtr
              JOIN refQuestionsAnswers AS qa ON qa.idTemplateRow = qtr.id
              JOIN refQstAnswers AS qsa ON qsa.id = qa.idValue
              WHERE qsa.deleted = 0 AND qa.deleted = 0
              AND qtr.id = ${item.idTemplateRow}
              ORDER BY qsa.Priority
              `;

            api.sql.exec(sqlQueryAnswers);
            const optionsList = api.sql.rows();

            if (optionsList.length) {
                optionsList.forEach((option) => {
                    templateRow.optionsList.push(option);
                });
            }

            // Получаем значения по умолчанию
            const sqlQueryDefValues = `SELECT
              id AS id,
              AnswerStr AS AnswerStr,
              AnswerNumber AS AnswerNumber,
              AnswerDate AS AnswerDate,
              AnswerID AS AnswerId
              FROM refQstTemplatesRowsDefValues
              WHERE idTemplateRow = ${item.idTemplateRow}`;

            api.sql.exec(sqlQueryDefValues);
            const defValues = api.sql.rows();

            if (defValues.length) {
                defValues.forEach((defVal) => {
                    templateRow.defValues.push(defVal);
                });
            }

            resp
                .find((template) => item.idTemplate === template.idTemplate)
                .topics.find((topic) => item.idTopic === topic.idTopic)
                .rows.push(templateRow);
        }
    });

    if (!checkHistory || Object.keys(questionsKeysWithHistory).length === 0) return resp[0];

    const documents = discoverDocs({ idTemplate, statuses: ['1'], todayOnly: false });
    if (!documents || !documents.length) return resp[0];
    const previousDoc = getDocument({ surveyDocId: documents[0].docId });
    const QWithMergedAnswers = mergeQuestionnaireAnswers({ QTo: resp[0], QFrom: previousDoc, questionsKeys: questionsKeysWithHistory });

    return QWithMergedAnswers;
}

function updateVerstamp(idDoc) {
    const verstamp = api.exchange.verstamp();

    const UpdateDocQueries = [
        `UPDATE DocJournal SET verstamp = ${verstamp} WHERE id = ${idDoc}`,
        `UPDATE dhSurvey SET verstamp = ${verstamp} WHERE id = ${idDoc}`,
        `UPDATE drSurvey SET verstamp = ${verstamp} WHERE idDoc = ${idDoc}`,
        `UPDATE drSurveyValues SET verstamp = ${verstamp} WHERE idDocRow IN
        (SELECT id FROM drSurvey WHERE idDoc = ${idDoc})`,
        `UPDATE drSurveyPhotos SET verstamp = ${verstamp} WHERE idDocRow IN
        (SELECT id FROM drSurvey WHERE idDoc = ${idDoc})`
    ];

    UpdateDocQueries.forEach((sqlQuery) => {
        api.sql.exec(sqlQuery);
    });
}

function stornDocument(idDoc, deleting) {
    const verstamp = api.exchange.verstamp();

    const UpdateDocQueries = [
        `UPDATE DocJournal SET idStatus = 3, ${deleting ? 'deleted = 1, ' : ''}
         verstamp = ${verstamp} WHERE id = ${idDoc}`,
        `UPDATE dhSurvey SET verstamp = ${verstamp} WHERE id = ${idDoc}`,
        `UPDATE drSurvey SET verstamp = ${verstamp} WHERE idDoc = ${idDoc}`,
        `UPDATE drSurveyValues SET verstamp = ${verstamp} WHERE idDocRow IN
        (SELECT id FROM drSurvey WHERE idDoc = ${idDoc})`
    ];

    if (mtVersion < 45) {
        UpdateDocQueries.push(
            `UPDATE drSurveyPhotos SET verstamp = ${verstamp} WHERE idDocRow IN 
            (SELECT id FROM drSurvey WHERE idDoc = ${idDoc})`
        );
    }

    UpdateDocQueries.forEach((sqlQuery) => {
        api.sql.exec(sqlQuery);
    });
}

function setZeroVerstamps(idDoc) {
    const sqlQueries = [
        `UPDATE DocJournal SET verstamp = 0 WHERE id = ${idDoc}`,
        `UPDATE dhSurvey SET verstamp = 0 WHERE id = ${idDoc}`,
        `UPDATE drSurvey SET verstamp = 0 WHERE idDoc = ${idDoc}`,
        `UPDATE drSurveyValues SET verstamp = 0 WHERE idDocRow IN
        (SELECT id FROM drSurvey WHERE idDoc = ${idDoc})`
    ];

    if (mtVersion < 45) {
        sqlQueries.push(
            `UPDATE drSurveyPhotos SET verstamp = 0 WHERE idDocRow IN
            (SELECT id FROM drSurvey WHERE idDoc = ${idDoc})`
        );
    }

    sqlQueries.forEach((sqlQuery) => {
        api.sql.exec(sqlQuery);
    });
}

/**
 * Функция сохранения документа ол
 * @param {object} options
 * @param {OKR_CRUD_Questionnaire} options.object - документ ол
 * @param {boolean} options.isDraft - признак сохранения в статусе черновика
 * @param {boolean} [options.isForced] - флаг создания новых айдишников
 * @param {boolean} [options.notUpload] - флаг невыгрузки документа после сохранения
 * @param {boolean} [options.stornDoc] - признак сторнирования документа
 */
function saveDocument({
    object, isDraft, isForced, notUpload = false, stornDoc = true
}) {
    api.log.info(`saveDocument in back start ${object.docId} ${isDraft}`);

    const regenerateIds = (object.idStatus !== '8' && !isForced);

    // Если (PV == 0) и (FV == 0) => obj.FV = docId, obj.PV = 0
    // Если stornDoc и FV и (PV == 0) => obj.FV = docId, obj.PV = doc.Id
    // Если stornDoc и FV и PV => obj.FV = FV, obj.PV = docId;
    // Если !stornDoc и FV и PV => obj.FV = docId, obj.PV = 0;

    if (object.docId !== '0' && object.idStatus === '1' && object.idFirstVersion !== '0' && stornDoc) {
        if (object.idPreviousVersion === '0') {
            object.idFirstVersion = object.docId;
            object.idPreviousVersion = object.docId;
        } else {
            object.idPreviousVersion = object.docId;
        }
    }

    object.idStatus = '8';

    let distributorId;

    if (object.docId !== '0' && regenerateIds) {
        distributorId = api.document.info(object.docId).distributorId;
        api.log.info(`check distr on storn doc ${distributorId}`);
    } else if (api.context.distributorId && api.context.distributorId != 0) {
        api.log.info(`check distr ${api.context.distributorId}`);
        distributorId = api.context.distributorId;
    } else {
        distributorId = getDistributorCoId();
    }

    if (object.docId === '0' || regenerateIds) {
        object.docId = api.getId.newId(distributorId);
    }

    if (object.idFirstVersion === '0' && object.idPreviousVersion === '0' && object.idStatus === '8') {
        object.idFirstVersion = object.docId;
    }

    if (!stornDoc) {
        object.idFirstVersion = object.docId;
        object.idPreviousVersion = '0';
    }

    const insSQLdj = `
      INSERT OR REPLACE INTO [DocJournal]([id],[PrintDocNum],[OpDate],[DateTimeStamp],[idStatus],
      [idCreator],[idClient],[${mtVersion >= 45 ? 'idOutlet' : 'idBuyPoint'}],[Amount],[idOperation],[idBaseDoc],[idFirstVersion],[idPreviousVersion],
      [PDADocNum],[idRoute],[deleted],[PrnDocNum],[CrDate],[idPhysicalPerson],[idVisit],[idAction],
      [idPosition],[Comment],[isEditOut],[ObjectType],[idExchangeState],[idBusinessStatus],[idState],verstamp)
      VALUES
      (
        ${object.docId}, --id
        '', --PrintDocNum
        DATETIME('now', 'localtime'), --OpDate
        DATETIME('now', 'localtime'), --DateTimeStamp 
        ${object.idStatus}, --idStatus
        ${object.idPhysicalPerson},  --idCreator
        0, --idClient 
        ${object.idOutlet}, --${mtVersion >= 45 ? 'idOutlet' : 'idBuyPoint'}
        0, --Amount
        33, --idOperation
        0, --idBaseDoc
        ${object.idFirstVersion}, --idFirstVersion
        ${object.idPreviousVersion}, --idPreviousVersion
        0, --PDADocNum
        ${object.idRoute}, --idRoute
        ${object.deleted}, --deleted
        '', --PrnDocNum
        DATETIME('now', 'localtime'), --CrDate
        ${object.idPhysicalPerson}, --idPhysicalPerson
        ${object.idVisit}, --idVisit
        0, --idAction
        ${object.idPosition}, --idPosition
        '${object.docComment}', --Comment
        0, --isEditOut
        null, --ObjectType
        0, --idExchangeState
        0, --idBusinessStatus
        1, --[idState]
        0 --verstamp 
      )`;

    api.sql.exec(insSQLdj);

    const insSQLsh = `
    INSERT OR REPLACE INTO [dhSurvey] ([id],[idTemplate],[idRoute], [verstamp])
      VALUES
      (
        ${object.docId}, --id
        ${object.idTemplate}, --idTemplate
        ${object.idRoute}, --idRoute
        0 --verstamp
      )`;

    api.sql.exec(insSQLsh);

    const sqlGetDrSurveyDB = `SELECT id AS id FROM drSurvey WHERE idDoc = ${object.docId}`;

    api.sql.exec(sqlGetDrSurveyDB);

    let drSurveyDB = api.sql.rows();

    drSurveyDB = drSurveyDB.reduce((acc, row) => (acc[row.id] = 0, acc), {});

    let idEnumsFalsifiedStatus;
    let idEnumsFile_LoadType;
    let idEnumsMimeType;
    let idEnumsDefectDetectionStatus;
    let idEnumsObject_Name;

    object.topics.forEach((topic) => {
        topic.rows.forEach((row) => {
            if (row.drSurveyId === '0' || regenerateIds) {
                row.drSurveyId = api.getId.newId(distributorId);
            }

            // Проставляет значение 1 для текущего row,
            if (drSurveyDB[row.drSurveyId] === 0) drSurveyDB[row.drSurveyId] = 1; // во фронте новая строка, которой нет в базе

            const insSQLdrSurvey = `
              INSERT OR REPLACE INTO [drSurvey] ([id],[idDoc],[idTemplateRow],[idQuestion],[idTopic], 
              ${mtVersion >= 45 ? ' [idPacket], ' : ''} [verstamp])
              VALUES
              (
                ${row.drSurveyId}, --id
                ${object.docId}, --idDoc
                ${row.idTemplateRow}, --idTemplateRow
                ${row.idQuestion}, --idQuestion
                ${topic.idTopic}, --idTopic
                ${mtVersion >= 45 ? `${row.idPacket}, --idPacket ` : ''}
                0 --verstamp
              )`;

            api.sql.exec(insSQLdrSurvey);

            // При первом заполнении при наличии множества ответов по умолчанию
            // Проверка по типу ответа ?????????
            if (row.defValues.length && row.answers && row.answers.length === 1 && Object.keys(row.answers[0]).every((key) => row.answers[0][key] === emptyAnswer[key])) {
                row.defValues.forEach((defAnswer, indexDefAnswer) => {
                    if (indexDefAnswer > row.answers.length - 1) {
                        row.answers.push({ drSurveyValueId: '0' });
                    }
                    row.answers[indexDefAnswer].AnswerStr = defAnswer.AnswerStr;
                    row.answers[indexDefAnswer].AnswerNumber = defAnswer.AnswerNumber;
                    row.answers[indexDefAnswer].AnswerDate = defAnswer.AnswerDate;
                    row.answers[indexDefAnswer].AnswerId = defAnswer.AnswerId;
                });
            }

            const sqlGetDrSurveyValuesDB = `SELECT id AS id FROM drSurveyValues WHERE idDocRow = ${row.drSurveyId}`;

            api.sql.exec(sqlGetDrSurveyValuesDB);

            let DrSurveyValuesDB = api.sql.rows();

            DrSurveyValuesDB = DrSurveyValuesDB.reduce((acc, row) => (acc[row.id] = 0, acc), {});

            row.answers.forEach((a) => {
                if (a.drSurveyValueId === '0' || regenerateIds) {
                    a.drSurveyValueId = api.getId.newId(distributorId);
                }

                if (DrSurveyValuesDB[a.drSurveyValueId] === 0) DrSurveyValuesDB[a.drSurveyValueId] = 1;

                a.AnswerStr = a.AnswerStr || '';
                a.AnswerNumber = a.AnswerNumber || '0';
                a.AnswerDate = a.AnswerDate || '1900-01-01 00:00:00';
                a.AnswerId = a.AnswerId || '0';

                const insSQLdrSurveyValues = `
                INSERT OR REPLACE INTO [drSurveyValues]([id],[idDocRow],[AnswerStr],[AnswerNumber],[AnswerDate],[AnswerID],verstamp)
                VALUES
                (
                  ${a.drSurveyValueId}, --id
                  ${row.drSurveyId}, --idDocRow
                  '${a.AnswerStr.replace(/'/g, "''")}', --AnswerStr
                  '${a.AnswerNumber}', --AnswerNumber
                  '${a.AnswerDate}', --AnswerDate
                  ${a.AnswerId}, --AnswerID
                  0 --verstamp
                )`;

                api.sql.exec(insSQLdrSurveyValues);
            });

            for (const dbRowId in DrSurveyValuesDB) {
                if (DrSurveyValuesDB[dbRowId] === 0) {
                    const sqlDeleteDrSurveyValues = `DELETE FROM drSurveyValues WHERE id = ${dbRowId}`;

                    api.sql.exec(sqlDeleteDrSurveyValues);
                }
            }

            if (row.questionType === 'Questions_AnswerType_Photo') {
                let DrSurveyPhotosDB;

                if (mtVersion < 45) {
                    const sqlGetDrSurveyPhotosDB = `SELECT id AS id FROM drSurveyPhotos WHERE idDocRow = ${row.drSurveyId}`;

                    api.sql.exec(sqlGetDrSurveyPhotosDB);

                    DrSurveyPhotosDB = api.sql.rows();

                    DrSurveyPhotosDB = DrSurveyPhotosDB.reduce((acc, row) => (acc[row.id] = 0, acc), {});

                    row.photos.forEach((p) => {
                        if (p.drSurveyPhotoId === '0' || regenerateIds) {
                            p.drSurveyPhotoId = api.getId.newId(distributorId);
                        }

                        p.photoFileName = (p.photoFileName.slice(0, 8) === 'file:///') ? p.photoFileName.slice(8) : p.photoFileName;

                        // Обрезаем полный путь для сохранения в базе, полный путь используем для процессинга
                        const photoName = p.photoFileName.substring(p.photoFileName.lastIndexOf('/') + 1);

                        const SQLiteNow = getSQLiteNow();

                        p.photoTime = p.photoTime || SQLiteNow;

                        if (DrSurveyPhotosDB[p.drSurveyPhotoId] === 0) DrSurveyPhotosDB[p.drSurveyPhotoId] = 1;

                        const IsFalsifiedStatusFieldExists = isFieldExistsCheck('drSurveyPhotos', 'falsifiedStatus');

                        idEnumsFalsifiedStatus = idEnumsFalsifiedStatus || getEnumsIdByCodeKey('FalsifiedStatus_NotGuaranteed');

                        const insSQL = `
                        INSERT OR REPLACE INTO [drSurveyPhotos]([id],[idDocRow],[photoTime],[photoFileName],
                        ${IsFalsifiedStatusFieldExists ? '[falsifiedStatus],' : ''} verstamp)
                        VALUES
                        (
                          ${p.drSurveyPhotoId}, --id
                          ${row.drSurveyId}, --idDocRow
                          '${p.photoTime}', --photoTime
                          '${photoName}', --photoFileName
                          ${IsFalsifiedStatusFieldExists ? `${idEnumsFalsifiedStatus}, --[falsifiedStatus] ` : ''}
                          0 --verstamp
                        )`;

                        api.sql.exec(insSQL);
                        api.warp.filesUpload.addFile(p.photoFileName, { 'tags': ['okr-survey'] });
                        p.photoFileName = photoName;
                    });

                    for (const dbRowId in DrSurveyPhotosDB) {
                        if (DrSurveyPhotosDB[dbRowId] === 0) {
                            const sqlDeleteDrRowsPhotos = `DELETE FROM drSurveyPhotos WHERE id = ${dbRowId}`;

                            api.sql.exec(sqlDeleteDrRowsPhotos);
                        }
                    }
                } else {
                    // Проверяем пришедшие файлы
                    if (!row.photos.length) {
                        if (row.idPacket !== '0') {
                            // мтшка создает пакет без файлов, если до этого был файлы, здесь пока пробую так
                            const sqlSetZeroPacket = `UPDATE drSurvey SET idPacket = 0 WHERE id = ${row.drSurveyId}`;

                            api.sql.exec(sqlSetZeroPacket);

                            row.idPacket = '0';
                        }

                        return;
                    }

                    if (row.idPacket !== '0') {
                        const sqlGetPhotoFilesDB = `
                        SELECT
                        f.FileName AS FileName
                        FROM drSurvey AS sr
                        JOIN refFilePacketsFiles AS fpf ON fpf.idPacket = sr.idPacket
                        JOIN refFiles AS f ON f.id = fpf.idFile
                        WHERE fpf.deleted = 0 AND fpf.idPacket = ${row.idPacket}
                        AND sr.id = ${row.drSurveyId}
                        ORDER BY f.id`;

                        api.sql.exec(sqlGetPhotoFilesDB);
                        DrSurveyPhotosDB = api.sql.rows();
                        DrSurveyPhotosDB = DrSurveyPhotosDB.map(({ FileName }) => getFileNameOfPath(FileName))
                            .sort();
                    }

                    const DrSurveyPhotosObj = row.photos.map(({ photoFileName }) => getFileNameOfPath(photoFileName))
                        .sort();

                    api.log.info('check photoArrays DrSurveyPhotosDB ' + JSON.stringify(DrSurveyPhotosDB));
                    api.log.info('check photoArrays DrSurveyPhotosObj ' + JSON.stringify(DrSurveyPhotosObj));

                    if (arraysEqual(DrSurveyPhotosDB, DrSurveyPhotosObj) && !regenerateIds) return;

                    api.log.info('создаем пакет');

                    // добавляем фото в базу
                    row.photos.forEach((p) => {
                        if (p.drSurveyPhotoId === '0') {
                            p.drSurveyPhotoId = api.getId.newId(distributorId);

                            p.photoFileName = (p.photoFileName.slice(0, 8) === 'file:///') ? p.photoFileName.slice(8) : p.photoFileName;

                            const photoName = p.photoFileName.slice(p.photoFileName.lastIndexOf('/') + 1);

                            const SQLiteNow = getSQLiteNow();

                            p.photoTime = p.photoTime || SQLiteNow;

                            idEnumsFile_LoadType = idEnumsFile_LoadType || getEnumsIdByCodeKey('File_LoadType_STDrive');
                            idEnumsMimeType = idEnumsMimeType || getEnumsIdByCodeKey('MimeType_JPEG');

                            const sqlInsRefFiles = `
                            INSERT INTO [refFiles]
                            ([id], [FileName], [Uri], [idLoadType], [idMimeType], [deleted], [verstampMt],
                            [verstamp], [FileCreatedDateTime] )
                            VALUES
                              (
                                ${p.drSurveyPhotoId}, --[id]
                                '${photoName}', --[FileName]
                                '', --[Uri]
                                ${idEnumsFile_LoadType}, --[idLoadType]
                                ${idEnumsMimeType}, --[idMimeType]
                                0, --[deleted]
                                0, --[verstampMt]
                                0, --[verstamp]
                                '${p.photoTime}' --[FileCreatedDateTime]
                              )`;

                            api.sql.exec(sqlInsRefFiles);

                            const refPhotoFilesId = api.getId.newId(distributorId);

                            idEnumsDefectDetectionStatus = idEnumsDefectDetectionStatus || getEnumsIdByCodeKey('DefectDetectionStatus_NoInfo');

                            const sqlInsRefPhotoFiles = `
                              INSERT INTO [refPhotoFiles]
                              ([id], [idFile], [falsifiedStatus], [DefectDetectionStatus], [verstamp])
                              VALUES
                              (
                                ${refPhotoFilesId}, --[id]
                                ${p.drSurveyPhotoId}, --[idFile]
                                0, --[falsifiedStatus]
                                ${idEnumsDefectDetectionStatus}, --[DefectDetectionStatus]
                                0 --[verstamp]
                              )`;

                            api.sql.exec(sqlInsRefPhotoFiles);

                            const sqlInsMtinternalRefFilesMeta = `
                              INSERT INTO [mtinternal_refFilesMeta]
                              ([id], [MTLocalPath])
                              VALUES
                              (
                                ${p.drSurveyPhotoId}, --[id]
                                'mtdata:${p.photoFileName.slice(p.photoFileName.indexOf('/db/'))}' --[MTLocalPath]
                              )`;

                            api.sql.exec(sqlInsMtinternalRefFilesMeta);

                            api.warp.filesUpload.addFile(p.photoFileName, { 'tags': ['okr-survey'] });

                            p.photoFileName = photoName;
                        }
                    });

                    // Обновляем пакет
                    const refFilePacketsId = api.getId.newId(distributorId);

                    idEnumsObject_Name = idEnumsObject_Name || getEnumsIdByCodeKey('Object_Name_Surveys');

                    const sqlInsRefFilePackets = `
                      INSERT INTO [refFilePackets]
                      ([id], [Name], [idBaseObject], [deleted], [verstamp])
                      VALUES
                      (
                        ${refFilePacketsId}, --[id]
                        NULL, --[Name]
                        ${idEnumsObject_Name}, --[idBaseObject]
                        0, --[deleted]
                        0 --[verstamp]
                      )`;

                    api.sql.exec(sqlInsRefFilePackets);

                    row.photos.forEach((p) => {
                        const refFilePacketsFilesId = api.getId.newId(distributorId);

                        const sqlInsRefFilePacketsFiles = `
                        INSERT INTO [refFilePacketsFiles]
                        ([id], [idPacket], [idFile], [Name], [Internal], [deleted], [priority], [verstamp])
                        VALUES
                        (
                          ${refFilePacketsFilesId}, --[id]
                          ${refFilePacketsId}, --[idPacket]
                          ${p.drSurveyPhotoId}, --[idFile]
                          NULL, --[Name]
                          0, --[Internal]
                          0, --[deleted]
                          0, --[priority]
                          0 --[verstamp]
                          )`;

                        api.sql.exec(sqlInsRefFilePacketsFiles);
                    });

                    const sqlSetNewPacket = `
                    UPDATE drSurvey SET idPacket = ${refFilePacketsId}
                    WHERE id = ${row.drSurveyId}`;

                    api.sql.exec(sqlSetNewPacket);

                    if (row.idPacket !== '0') {
                        // removeFilePacket
                    }

                    row.idPacket = `${refFilePacketsId}`;
                }
            }
        });
    });

    for (const dbRowId in drSurveyDB) {
        if (drSurveyDB[dbRowId] === 0) {
            const deleteRowsQueries = [
                `DELETE FROM drSurveyValues WHERE idDocRow = ${dbRowId}`,
                `DELETE FROM drSurvey WHERE id = ${dbRowId}`
            ];

            if (mtVersion < 45) {
                deleteRowsQueries.push(`DELETE FROM drSurveyPhotos WHERE idDocRow = ${dbRowId}`);
            }

            deleteRowsQueries.forEach((sqlQuery) => {
                api.sql.exec(sqlQuery);
            });
        }
    }

    if (!isDraft) {
        let MTDocValidation;

        if (mtVersion >= 45) {
            MTDocValidation = api.survey.doc.validate(object.docId);
        } else {
            MTDocValidation = api.document.validate(object.docId);
        }

        if (notUpload) setZeroVerstamps(object.docId);
        api.log.info(`ПРоверка валидации ${JSON.stringify(MTDocValidation)}`);
        if (MTDocValidation) {
            if (object.idPreviousVersion !== '0') {
                const sqlPrevVersionOpDate = `UPDATE DocJournal SET OpDate = 
                (SELECT CrDate FROM DocJournal WHERE id = ${object.idPreviousVersion})
                WHERE id = ${object.idPreviousVersion}`;
                api.sql.exec(sqlPrevVersionOpDate);
            }

            api.log.info(`saveDocument in back end ${object.docId} ${isDraft}`);

            return object;
        }
    }

    api.log.info(`saveDocument in back end ${object.docId} ${isDraft}`);

    return object;
}

/**
 * Функция поиска шаблонов ОЛ по имени или списку имен
 * @param {object} options 
 * @param {string | string[]} options.templateNames - названия шаблона или список названий
 * @param {string} [options.templateComment] - комментарий для поиска ол (LIKE '%${templateComment}}%')
 * @param {string} [options.idOutlet] - id торговой точки для фильтрации по сету
 * @param {string} [options.idPosition] - id позиции для фильтрации по сету
 * @param {string} [options.idDistributor] - id дистра для фильтрации по сету
 * @param {string} [options.NoSetsCheck] - отключение фильтрации шаблона по сету
 * @returns {Array<{id: string, Name: string, idFirstVersion: string}>}
 */
function discoverTemplates({
    templateNames: templateNamesArg, templateComment = '', idOutlet: idOutletArg, idPosition: idPositionArg, idDistributor: idDistributorArg, NoSetsCheck = false
}) {
    const idOutlet = idOutletArg || api.context.outletId;
    const idPosition = idPositionArg || api.context.positionId;
    let idDistributor;

    if (idDistributorArg) {
        idDistributor = idDistributorArg;
    } else if (api.context.distributorId && api.context.distributorId !== '0') {
        idDistributor = api.context.distributorId;
    } else {
        idDistributor = getDistributorCoId();
    }

    let IdsFromSets = [];

    if (!NoSetsCheck) {
        IdsFromSets = api.sets.idItemsOPDS(idOutlet, idPosition, idDistributor);
    }

    let templateNames = [];

    if (templateNamesArg) {
        templateNames = Array.isArray(templateNamesArg) ? templateNamesArg : [templateNamesArg];
        templateNames = templateNames.map((n) => `'${n}'`);
    }

    const sqlDiscoverTemplates = `
      SELECT
      templ.id AS id,
      templ.Name AS Name,
      templ.idFirstVersion as idFirstVersion
      FROM refQstTemplates AS templ
      JOIN (
      SELECT idItem AS idItem, max(EventDate) AS EventDate FROM refPropertiesHistory AS ph
      WHERE date(ph.EventDate) <= date('now', 'localtime')
      GROUP BY idItem
      ) AS phDate ON phDate.idItem = templ.id
      JOIN refPropertiesHistory AS ph ON ph.EventDate = phDate.EventDate AND ph.idItem = phDate.idItem
      WHERE (
      templ.Name IN (${templateNames.join(', ')})
      ${templateComment.length ? `OR templ.Comment LIKE '%${templateComment}}%'` : ''}
      ) 
      AND templ.deleted = 0
      AND ph.idEvent = 133 AND ph.deleted = 0 
      ${!NoSetsCheck ? `AND templ.id IN (${IdsFromSets.join(', ')})` : ''}
      ORDER BY templ.Name`;

    api.log.info(`Проверка запроса sqlDiscoverTemplates ${sqlDiscoverTemplates}`);

    api.sql.exec(sqlDiscoverTemplates);
    const res = api.sql.rows();

    return res;
}

/**
 * Функция поиска документов ОЛ по id шаблона
 * @param {object} options
 * @param {string} options.idTemplate
 * @param {string} [options.idOutlet]
 * @param {string} [options.idVisit]
 * @param {string[]} [options.statuses] - Список статусов доков в DocJournal
 * @param {boolean} [options.todayOnly] - Флаг поиска только сегодняшних доков. По умолчанию true
 * @returns {Array<{docId: string, idStatus: string, OpDate: string, idTemplate: string}>}
 */
function discoverDocs({
    idTemplate, idOutlet, idVisit, statuses = ['8', '1'], todayOnly = true
}) {
    if (!idTemplate) return;
    const contextMT = api.context;
    // idVisit = idVisit || contextMT.visitId;

    idOutlet = idOutlet || contextMT.outletId;

    const sqlDiscoverDocs = `
      SELECT 
      dj.id AS docId,
      dj.idStatus AS idStatus,
      dj.OpDate AS OpDate,
      sh.idTemplate AS idTemplate
      FROM DocJournal AS dj
      JOIN dhSurvey AS sh ON sh.id = dj.id
      JOIN refQstTemplates AS qt ON qt.id = sh.idTemplate
      WHERE qt.idFirstVersion = (
          SELECT idFirstVersion FROM refQstTemplates WHERE id = ${idTemplate}
      )
      ${(idVisit && todayOnly) ? `AND dj.idVisit = ${idVisit} ` : ''}
      AND dj.${mtVersion >= 45 ? 'idOutlet' : 'idBuyPoint'} = ${idOutlet}
      AND dj.idOperation = 33
      AND dj.deleted = 0
      AND dj.idStatus IN (${statuses.join(', ')}) 
      AND date(dj.crDate) <= date('now', 'localtime')
      ${todayOnly ? 'AND date(dj.crDate) >= date(\'now\', \'start of day\', \'localtime\')' : ''}
      ORDER BY dj.idStatus DESC,  dj.opDate DESC`;

    api.log.info(`Проверка запроса sqlDiscoverDocs ${sqlDiscoverDocs}`);
    api.sql.exec(sqlDiscoverDocs);
    const res = api.sql.rows();

    return res;
}


/**
 * Функция получения из базы документа ол
 * @param {object} options
 * @param {string} options.surveyDocId - id документа
 * @returns {OKR_CRUD_Questionnaire}
 */
function getDocument({ surveyDocId }) {
    api.log.info(`Проверка входа getDocument surveyDocId ${surveyDocId}`);

    if (!surveyDocId) return;
    const getIdTemplateSql = `SELECT idTemplate AS idTemplate FROM dhSurvey WHERE id = ${surveyDocId}`;

    api.sql.exec(getIdTemplateSql);
    const { idTemplate } = api.sql.rows()[0];

    if (!idTemplate) return;

    const getIdTemplateActualSql = `
    SELECT qt.id AS idTemplate FROM refQstTemplates AS qt 
    WHERE qt.deleted = 0 AND qt.idFirstVersion IN
    (SELECT idFirstVersion AS idFirstVersion FROM
    refQstTemplates WHERE id = ${idTemplate})`;

    api.sql.exec(getIdTemplateActualSql);

    const idTemplateActual = api.sql.rows()[0].idTemplate;
    const isDocTemplateActual = idTemplate === idTemplateActual;

    let QuestionnaireObject = createQuestionnaireObject({ idTemplate: idTemplate, checkHistory: false });
    const isPreviousTemplateValid = Boolean(QuestionnaireObject);

    if (!isPreviousTemplateValid) {
        if (isDocTemplateActual) return;
        QuestionnaireObject = createQuestionnaireObject({ idTemplate: idTemplateActual, checkHistory: false });
        if (!QuestionnaireObject) return;
    }

    const selectSql = `
      SELECT
      dj.id AS docId,
      dj.OpDate AS OpDate,
      dj.idFirstVersion AS idFirstVersion,
      dj.idPreviousVersion AS idPreviousVersion,
      dj.${mtVersion >= 45 ? 'idOutlet' : 'idBuyPoint'} AS idOutlet,
      dj.idVisit AS idVisit,
      dj.Comment AS docComment,
      dj.idPhysicalPerson AS idPhysicalPerson,
      dj.idRoute AS idRoute,
      dj.idPosition AS idPosition,
      dj.idStatus AS idStatus,
      dj.deleted AS deleted
      FROM docJournal AS dj
      WHERE dj.id = ${surveyDocId}`;

    api.sql.exec(selectSql);
    const docInfo = api.sql.rows();

    QuestionnaireObject.docId = docInfo[0].docId;
    QuestionnaireObject.OpDate = docInfo[0].OpDate;
    QuestionnaireObject.idFirstVersion = docInfo[0].idFirstVersion;
    QuestionnaireObject.idPreviousVersion = docInfo[0].idPreviousVersion;
    QuestionnaireObject.idOutlet = docInfo[0].idOutlet;
    QuestionnaireObject.idVisit = docInfo[0].idVisit;
    QuestionnaireObject.docComment = docInfo[0].docComment;
    QuestionnaireObject.idStatus = docInfo[0].idStatus;
    QuestionnaireObject.deleted = docInfo[0].deleted;

    QuestionnaireObject.idPhysicalPerson = docInfo[0].idPhysicalPerson;
    QuestionnaireObject.idRoute = docInfo[0].idRoute;
    QuestionnaireObject.idPosition = docInfo[0].idPosition;

    if (!isPreviousTemplateValid) {
        return QuestionnaireObject;
    }

    QuestionnaireObject.topics.forEach((topic) => {
        const rowsDB = [];
        topic.rows.forEach((row) => {
            const selectSqlDrSurveyId = `
            SELECT 
            sr.id AS drSurveyId,
            sr.idQuestion AS idQuestion,
            sr.idTemplateRow AS TemplateRow,
            ${mtVersion >= 45 ? 'sr.idPacket AS idPacket, ' : ''}
            sr.idTopic AS idTopic
            FROM drSurvey AS sr
            WHERE sr.idDoc = ${surveyDocId}
            -- AND sr.idQuestion = ${row.idQuestion} возможно несколько записей в drSurvey на один idTemplateRow, например, если указан idQuestionClassifier
            AND sr.idTemplateRow = ${row.idTemplateRow}
            AND sr.idTopic = ${topic.idTopic}`;

            api.sql.exec(selectSqlDrSurveyId);
            const res = api.sql.rows();

            if (!res.length) {
                // нет строки с ответом, проставляется дефолт из шаблона
                rowsDB.push(row);

                return;
            }

            res.forEach((r) => {
                const rowDB = JSON.parse(JSON.stringify(row));
                rowDB.answers = [];
                rowDB.photos = [];

                rowDB.drSurveyId = r.drSurveyId;
                rowDB.idQuestion = r.idQuestion;

                if (mtVersion >= 45) {
                    rowDB.idPacket = r.idPacket;
                }

                const selectSqlDrSurveyValues = `
                SELECT
                id AS drSurveyValueId,
                AnswerDate AS AnswerDate,
                AnswerID AS AnswerId,
                AnswerNumber AS AnswerNumber,
                AnswerStr AS AnswerStr
                FROM drSurveyValues WHERE idDocRow = ${rowDB.drSurveyId}`;

                api.sql.exec(selectSqlDrSurveyValues);
                const rAnswers = api.sql.rows();

                rAnswers.forEach((rAnswer) => {
                    rowDB.answers.push({
                        drSurveyValueId: rAnswer.drSurveyValueId,
                        AnswerDate: (rAnswer.AnswerDate ? rAnswer.AnswerDate : '1900-01-01 00:00:00.00'),
                        AnswerId: rAnswer.AnswerId,
                        AnswerNumber: rAnswer.AnswerNumber,
                        AnswerStr: rAnswer.AnswerStr
                    });
                });

                if (row.questionType === 'Questions_AnswerType_Photo') {
                    let rPhotos;
                    let selectSqlDrSurveyPhotos;

                    if (mtVersion < 45) {
                        selectSqlDrSurveyPhotos = `
                        SELECT
                        id AS drSurveyPhotoId,
                        photoTime AS photoTime,
                        photoFileName AS photoFileName
                        FROM drSurveyPhotos WHERE idDocRow = ${rowDB.drSurveyId}`;

                        api.sql.exec(selectSqlDrSurveyPhotos);
                        rPhotos = api.sql.rows();

                        rPhotos.forEach((rPhoto) => {
                            rowDB.photos.push({
                                drSurveyPhotoId: rPhoto.drSurveyPhotoId,
                                photoTime: rPhoto.photoTime,
                                photoFileName: rPhoto.photoFileName
                            });
                        });
                    } else {
                        selectSqlDrSurveyPhotos = `
                        SELECT
                        f.id AS drSurveyPhotoId,
                        f.FileCreatedDateTime AS photoTime,
                        f.FileName AS photoFileName
                        FROM drSurvey AS sr
                        JOIN refFilePacketsFiles AS fpf ON fpf.idPacket = sr.idPacket
                        JOIN refFiles AS f ON f.id = fpf.idFile
                        WHERE fpf.deleted = 0 AND sr.id = ${rowDB.drSurveyId}
                        ORDER BY f.FileCreatedDateTime, f.id`;

                        api.sql.exec(selectSqlDrSurveyPhotos);
                        rPhotos = api.sql.rows();

                        rPhotos.forEach((rPhoto) => {
                            rowDB.photos.push({
                                drSurveyPhotoId: rPhoto.drSurveyPhotoId,
                                photoTime: rPhoto.photoTime,
                                photoFileName: rPhoto.photoFileName
                            });
                        });
                    }
                }

                rowsDB.push(rowDB);
            });
        });
        topic.rows = rowsDB;
    });

    if (isPreviousTemplateValid && !isDocTemplateActual) {
        api.log.info(`check QuestionnaireObject idTemplate ${idTemplate}`);
        api.log.info(`check QuestionnaireObject ${JSON.stringify(QuestionnaireObject)}`);

        const QuestionnaireObjectActual = createQuestionnaireObject({ idTemplate: idTemplateActual, checkHistory: false });

        api.log.info(`check QuestionnaireObjectActual idTemplate ${idTemplateActual}`);
        api.log.info(`check QuestionnaireObjectActual ${JSON.stringify(QuestionnaireObjectActual)}`);

        QuestionnaireObjectActual.idFirstVersion = QuestionnaireObject.idFirstVersion;
        QuestionnaireObjectActual.idPreviousVersion = QuestionnaireObject.docId;

        QuestionnaireObjectActual.OpDate = QuestionnaireObject.OpDate;
        QuestionnaireObjectActual.idOutlet = QuestionnaireObject.idOutlet;
        QuestionnaireObjectActual.idVisit = QuestionnaireObject.idVisit;
        QuestionnaireObjectActual.docComment = QuestionnaireObject.docComment;
        QuestionnaireObjectActual.idStatus = QuestionnaireObject.idStatus;
        QuestionnaireObjectActual.deleted = QuestionnaireObject.deleted;

        QuestionnaireObjectActual.idPhysicalPerson = QuestionnaireObject.idPhysicalPerson;
        QuestionnaireObjectActual.idRoute = QuestionnaireObject.idRoute;
        QuestionnaireObjectActual.idPosition = QuestionnaireObject.idPosition;

        QuestionnaireObject = mergeQuestionnaireAnswers({ QTo: QuestionnaireObjectActual, QFrom: QuestionnaireObject });

        api.log.info(`check QuestionnaireObject res ${JSON.stringify(QuestionnaireObject)}`);
    }

    return QuestionnaireObject;
}

