/**
 * Получение условий(меты) ОЛ по idFirstVersion или id шаблона 
 * @param {object} options 
 * @param {string} [options.idTemplate]
 * @param {string} [options.idTemplateFV]
 * @return {string}
 */
function getQuestionnaireMeta({ idTemplate, idTemplateFV }) {
    if (!idTemplate && !idTemplateFV) return '';
    const isTableExists = isTableExistsCheck('refQstTemplatesCondition');

    if (!isTableExists) return '';

    const sqlQueryCondition = `
    SELECT Condition AS Condition FROM refQstTemplatesCondition AS qtc
    WHERE qtc.deleted = 0
    ${idTemplateFV ? ` AND qtc.idTemplateFirstVersion = '${idTemplateFV}'` : ''}
    ${idTemplate ? ` AND qtc.idTemplateFirstVersion IN (SELECT idFirstVersion FROM refQstTemplates WHERE id = ${idTemplate} )` : ''}
    `;

    api.sql.exec(sqlQueryCondition);
    const sqlQueryConditionRes = api.sql.rows();

    if (sqlQueryConditionRes[0]) {
        return sqlQueryConditionRes[0].Condition;
    }

    return '';
}

